&reftitle.description;
public static boolYaf_Registry::set stringname mixedvalue
Stocke une valeur dans le registre. Définir un nom déjà existant écrase sa valeur précédente.

  &reftitle.examples;

   Exemple avec Yaf_Registry::set


<?php
class Bootstrap extends Yaf_Bootstrap_Abstract
{
    public function _initRedis(Yaf_Dispatcher $dispatcher)
    {
        $config = Yaf_Application::app()->getConfig()->redis;

        $redis = new Redis();
        $redis->connect($config->host, $config->port);

        /* la connexion est désormais disponible pour toute l'application */
        Yaf_Registry::set("redis", $redis);
    }
}
?>
